<?php
require_once __DIR__.'/../../config/conexion.php';require_once __DIR__.'/../Models/PlanillaPagoModel.php';class PlanillaPagoController{private function m(){global $conexion;return new PlanillaPagoModel($conexion);}function index():void{autorizar('planilla.cerrar');try{extract($this->m()->datos((int)($_GET['id']??0)));}catch(Throwable $e){mensaje('error',$e->getMessage());header('Location:index.php?url=planilla');exit;}require __DIR__.'/../Views/layouts/header.php';require __DIR__.'/../Views/layouts/navbar.php';require __DIR__.'/../Views/planilla/pagos.php';require __DIR__.'/../Views/layouts/footer.php';}function registrar():void{autorizar('planilla.cerrar');validarCsrf();$id=(int)($_POST['id_periodo_pago']??0);try{$id=$this->m()->registrar($_POST,(int)$_SESSION['usuario']['id_usuario']);mensaje('success','Pago de planilla registrado.');}catch(Throwable $e){mensaje('error',$e->getMessage());}header('Location:index.php?url=planilla_pagos&id='.$id);exit;}function anular():void{autorizar('planilla.cerrar');validarCsrf();$id=(int)($_POST['id_periodo_pago']??0);try{$id=$this->m()->anular((int)($_POST['id_pago_planilla']??0),$_POST['motivo_anulacion']??'',(int)$_SESSION['usuario']['id_usuario']);mensaje('success','Pago anulado y saldo restaurado.');}catch(Throwable $e){mensaje('error',$e->getMessage());}header('Location:index.php?url=planilla_pagos&id='.$id);exit;}}
